feedbackvariables.text:
/*    TESTS DES PLACEMENTS    */

/* On vérifie la présence exacte de la chaîne */


test_exact:is(ssearch("zone_sys:Bille de métal", ans1) # false);
/* On crée une liste des mots attendus pour la suite */
mots_attendus: ["Table", "Terre","Aimant"];

/* On vérifie si TOUS les mots sont présents dans la réponse */
tous_presents: all_listp(lambda([x], ssearch(x, ans1) # false), mots_attendus);


/* pour les flèches*/
/* On vérifie la présence exacte des chaînes pour les objets */
test_fleche1 : is(
    (ssearch("Bille de métal-Table-solid", ans1) # false) or 
    (ssearch("Table-Bille de métal-solid", ans1) # false)
);
test_fleche1_wrong : is(
    (ssearch("Bille de métal-Table-dashed", ans1) # false) or 
    (ssearch("Table-Bille de métal-dashed", ans1) # false)
);
/* Test pour la flèche entre bille et aimant (les deux sens acceptés) */
test_fleche2 : is(
    (ssearch("Aimant-Bille de métal-dashed", ans1) # false) or 
    (ssearch("Bille de métal-Aimant-dashed", ans1) # false)
);
test_fleche2_wrong : is(
    (ssearch("Aimant-Bille de métal-solid", ans1) # false) or 
    (ssearch("Bille de métal-Aimant-solid", ans1) # false)
);
/* Test pour la flèche entre bille et Terre (les deux sens acceptés) */
test_fleche3 : is(
    (ssearch("Terre-Bille de métal-dashed", ans1) # false) or 
    (ssearch("Bille de métal-Terre-dashed", ans1) # false)
);
test_fleche3_wrong : is(
    (ssearch("Terre-Bille de métal-solid", ans1) # false) or 
    (ssearch("Bille de métal-Terre-solid", ans1) # false)
);

/*    TESTS DES PLACEMENTS    */

/* On vérifie la présence exacte des chaines nip enlevées*/
test_1:is(ssearch("nipaccélération", ans1) # false);
test_2:is(ssearch("nipvitesse", ans1) # false);

/*On verifie que tout les hors système sont présents */
tous_hors_sys_ok: test_1 and test_2;
